package com.vocal.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.util.*;
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder @Entity @Table(name="products", indexes={@Index(name="idx_product_slug", columnList="slug"),@Index(name="idx_product_name", columnList="name")})
public class Product extends BaseEntity { @Column(nullable=false) private String name; @Column(nullable=false, unique=true) private String slug; @Column(columnDefinition="TEXT") private String description; @Column(nullable=false, precision=12, scale=2) private BigDecimal price; @Column(precision=12, scale=2) private BigDecimal compareAtPrice; @ElementCollection @CollectionTable(name="product_images") private List<String> imageUrls=new ArrayList<>(); @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="category_id") private Category category; @Builder.Default private boolean active=true; @Builder.Default private boolean featured=false; @Builder.Default private boolean bestSeller=false; @Builder.Default @OneToMany(mappedBy="product", cascade=CascadeType.ALL, orphanRemoval=true) private List<ProductVariant> variants=new ArrayList<>(); }
